// FormLane — one direction of a relationship's communication forms: a from/to header over a stack of
// FormChips, or an empty note. Promoted from harvested into base-studio-code, refactored to use the
// real Box/Row/Stack/Text primitives and the promoted teams-form-chip component instead of local
// raw-div redeclarations.
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { FormChip, type CommunicationForm } from "@/components/teams-form-chip";

const DEMO_FORMS: CommunicationForm[] = [
  { id: "status", label: "status update", color: "var(--accent)", arrow: "→", blurb: "A brief on progress, blockers, and next steps; posted on a cadence." },
  { id: "escalation", label: "escalation", color: "var(--danger)", arrow: "⇈", blurb: "Raised when a blocker needs attention now; interrupts the cadence." },
];

export function FormLane({ from = "builder-1", to = "reviewer-2", forms = DEMO_FORMS, hue = 250 }: { from?: string; to?: string; forms?: CommunicationForm[]; hue?: number }) {
  return (
    <Box style={{ border: "1px solid var(--border-soft)", borderRadius: 11, overflow: "hidden", background: "var(--bg-soft)" }}>
      <Row gap={7} align="center" style={{ padding: "9px 12px", background: "var(--bg-elev)", borderBottom: "1px solid var(--border-soft)" }}>
        <Text as="span" weight={600} size={11.5}>{from}</Text>
        <Text as="span" weight={700} style={{ color: `oklch(0.72 0.13 ${hue})` }}>→</Text>
        <Text as="span" weight={600} size={11.5}>{to}</Text>
      </Row>
      <Box style={{ padding: "11px 12px" }}>
        {forms.length === 0
          ? <Text as="span" size={11} tone="dim" style={{ fontStyle: "italic" }}>no forms this direction</Text>
          : <Stack gap={7}>{forms.map((f) => <FormChip key={f.id} form={f} note />)}</Stack>}
      </Box>
    </Box>
  );
}
